const $=(s,root=document)=>root.querySelector(s);
const esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icons={home:'<path d="m3 10 9-7 9 7v10a1 1 0 0 1-1 1h-5v-8H9v8H4a1 1 0 0 1-1-1z"/>',overview:'<path d="M12 3v9h9A9 9 0 1 1 12 3Z"/><path d="M16 3a8 8 0 0 1 5 5h-5z"/>',budgets:'<rect x="3" y="13" width="4" height="8" rx="1"/><rect x="10" y="4" width="4" height="17" rx="1"/><rect x="17" y="9" width="4" height="12" rx="1"/>',settings:'<circle cx="5" cy="12" r="1"/><circle cx="12" cy="12" r="1"/><circle cx="19" cy="12" r="1"/>',search:'<circle cx="10" cy="10" r="6"/><path d="m15 15 6 6"/>'};
const svg=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${icons[name]}</svg>`;
let state,blocked=false;
try{state=loadState();}catch{blocked=true;state=initialState();}
let month=today().slice(0,7),page='home',overviewType='expense',period='month',chartMode='bar',filter={query:'',type:'all',category:'all',label:'all',from:'',to:''},showFilters=false;
let overviewScale='month',homeScale='month';
const budgetSelectedPeriods=new Map();
const viewScale=()=>page==='home'?homeScale:page==='overview'?overviewScale:'month';
let toastTimer,dictationUndo=null;
function toast(message,undo=null){const el=$('#toast');dictationUndo=undo;el.innerHTML=`<span>${esc(message)}</span>${undo?'<button type="button" data-action="undo-dictation">Undo</button>':''}`;el.classList.toggle('has-action',!!undo);el.classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>{el.classList.remove('show');dictationUndo=null;},undo?2000:4000);}
const dictationCallbacks={onState:listening=>{const button=$('#dictate-transaction');if(button){button.classList.toggle('listening',listening);button.setAttribute('aria-pressed',String(listening));button.setAttribute('aria-label',listening?'Stop dictation':'Dictate transaction');}const status=$('#dictation-status');if(status&&listening)status.textContent='Starting microphone… wait before speaking.';else if(status&&/^(Starting|Restarting|Listening|Voice detected|Finishing)/.test(status.textContent))status.textContent='Dictation stopped. Tap mic to try again.';},onTranscript:applyDictation,onStatus:message=>{const status=$('#dictation-status');if(status)status.textContent=message;},onError:message=>{const status=$('#dictation-status');if(status)status.textContent=message;}};
const dictation=createDictation({...dictationCallbacks,isComplete:text=>parseDictation(text,state.categories).valid});


function applyTheme(){const pref=state.settings.theme;document.documentElement.dataset.theme=pref==='system'?(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'):pref==='blue'?'light':pref;const accent=getComputedStyle(document.documentElement).getPropertyValue('--green').trim();$('meta[name="theme-color"]').content=accent;}
function commit(mutator){
  if(blocked){toast('Restore a backup or reset unreadable data in Settings before making changes.');return false;}
  const next=structuredClone(state);
  try{mutator(next);saveState(next);state=next;applyTheme();render();return true;}catch(e){toast(e.name==='QuotaExceededError'?'Storage is full. Export a backup before freeing space.':`Could not save: ${e.message}`);return false;}
}
function catchUp(){if(blocked)return;const next=structuredClone(state);const n=processRules(next);if(n||JSON.stringify(next.rules)!==JSON.stringify(state.rules)){try{saveState(next);state=next;if(n)toast(`${n} recurring ${n===1?'transaction':'transactions'} added.`);}catch{toast('Recurring entries could not be saved. Please export a backup.');}}}
catchUp();applyTheme();
function cat(id){return state.categories.find(c=>c.id===id);}
function categoryIcon(c){return `<span class="category-icon" style="background:${c.color}20">${esc(c.icon)}</span>`;}
function monthControl(){return `<div class="month-switch"><button class="icon-btn" data-action="prev-month" aria-label="Previous month">‹</button><input class="month-input" aria-label="Selected month" id="month" type="month" min="1900-01" max="2200-12" value="${month}"><button class="icon-btn" data-action="next-month" aria-label="Next month">›</button></div>`;}
function head(title,subtitle=''){return `<div class="page-head"><div>${subtitle?`<div class="eyebrow">${subtitle}</div>`:''}<h1>${title}</h1></div>${page==='settings'?'':monthControl()}</div>`;}
const actual=()=>state.transactions.filter(t=>t.date<=today());
function empty(title,description,action='',button=''){return `<div class="empty"><div class="empty-icon">◈</div><h3>${title}</h3><p>${description}</p>${action?`<button class="btn secondary" data-action="${action}">${button}</button>`:''}</div>`;}
function historyRows(){return actual().filter(t=>{
  const c=cat(t.categoryId);const query=[t.description,c.name,...t.labelIds.map(id=>state.labels.find(l=>l.id===id)?.name||'')].join(' ').toLowerCase();
  return (filter.from||filter.to?(!filter.from||t.date>=filter.from)&&(!filter.to||t.date<=filter.to):t.date.startsWith(homeScale==='year'?month.slice(0,4):month))&&(filter.type==='all'||t.type===filter.type)&&(filter.category==='all'||t.categoryId===filter.category)&&(filter.label==='all'||t.labelIds.includes(filter.label))&&query.includes(filter.query.toLowerCase());
}).sort((a,b)=>b.date.localeCompare(a.date));}
function transactionRow(t){const c=cat(t.categoryId);return `<button class="transaction" data-action="edit-transaction" data-id="${esc(t.id)}">${categoryIcon(c)}<span class="transaction-copy"><strong>${esc(c.name)}</strong><p>${esc(t.description||t.labelIds.map(id=>state.labels.find(l=>l.id===id)?.name).join(' · ')||dateLabel(t.date))}</p></span><span class="transaction-amount ${t.type==='income'?'green':''}">${t.type==='expense'?'−':'+'}${money(t.amount)}${t.excluded||t.ruleId?`<small>${t.excluded?'Excluded':FREQUENCIES[state.rules.find(r=>r.id===t.ruleId)?.frequency]||'Recurring'}</small>`:''}</span></button>`;}
function historyHtml(rows=historyRows()){rows=[...rows].sort((a,b)=>b.date.localeCompare(a.date));let out='',current='';for(const t of rows){if(t.date!==current){if(current)out+='</div>';current=t.date;const day=rows.filter(x=>x.date===current);const s=summary(day);out+=`<div class="day-header"><span>${current===today()?'Today':dateLabel(current)}</span><span>${money(s.income-s.expense)}</span></div><div class="transaction-list">`;}out+=transactionRow(t);}return out+(current?'</div>':empty('No transactions yet','Add a transaction, or adjust your filters.','add','Add transaction'));}
function filtersHtml(){return `<div class="filter-bar"><div class="search">${svg('search')}<input id="search" aria-label="Search transactions" placeholder="Search transactions" value="${esc(filter.query)}" type="search"></div><button class="filter-button" data-action="toggle-filters" aria-expanded="${showFilters}">Filters${Object.entries(filter).some(([k,v])=>k!=='query'&&v!=='all'&&v!=='')?' ·':''}</button></div>${showFilters?`<div class="card filters"><label>Type<select id="filter-type"><option value="all">Income & expenses</option><option value="expense" ${filter.type==='expense'?'selected':''}>Expenses</option><option value="income" ${filter.type==='income'?'selected':''}>Income</option></select></label><label>Category<select id="filter-category"><option value="all">All categories</option>${state.categories.map(c=>`<option value="${esc(c.id)}" ${filter.category===c.id?'selected':''}>${esc(c.name)}</option>`).join('')}</select></label><label>Label<select id="filter-label"><option value="all">All labels</option>${state.labels.map(l=>`<option value="${esc(l.id)}" ${filter.label===l.id?'selected':''}>${esc(l.name)}</option>`).join('')}</select></label><label>From<input id="filter-from" type="date" min="1900-01-01" max="2200-12-31" value="${filter.from}"></label><label>To<input id="filter-to" type="date" min="1900-01-01" max="2200-12-31" value="${filter.to}"></label><button class="text-btn" data-action="clear-filters">Clear filters</button></div>`:''}`;}
function cashChart(mode='bar',scale='month'){const months=Array.from({length:6},(_,i)=>shiftMonth(month,(i-5)*(scale==='year'?12:1)));const vals=months.map(m=>summary(actual().filter(t=>t.date.startsWith(scale==='year'?m.slice(0,4):m))));const max=Math.max(100,...vals.flatMap(v=>[v.income,v.expense]));const top=15,bottom=130,height=115;
  let content=[0,.5,1].map(n=>`<line x1="0" y1="${bottom-height*n}" x2="420" y2="${bottom-height*n}" stroke="currentColor" opacity=".16" stroke-dasharray="4 5"/><text x="0" y="${bottom-height*n-5}" fill="currentColor" font-size="10">${n?money(Math.round(max*n)).replace(/\.00$/,''):'0'}</text>`).join('');
  const xs=months.map((m,i)=>42+i*66);
  if(mode==='line'){for(const [key,color] of [['income','var(--chart-income)'],['expense','var(--chart-expense)']])content+=`<polyline points="${vals.map((v,i)=>`${xs[i]+13},${bottom-height*v[key]/max}`).join(' ')}" fill="none" stroke="${color}" stroke-width="3"/>`;}
  else vals.forEach((v,i)=>{content+=`<rect x="${xs[i]}" y="${bottom-height*v.income/max}" width="12" height="${height*v.income/max}" rx="3" fill="var(--chart-income)"/><rect x="${xs[i]+15}" y="${bottom-height*v.expense/max}" width="12" height="${height*v.expense/max}" rx="3" fill="var(--chart-expense)"/>`;});
  content+=months.map((m,i)=>`<text x="${xs[i]+13}" y="152" text-anchor="middle" fill="currentColor" font-size="11" ${m===month?'font-weight="700"':''}>${scale==='year'?m.slice(0,4):new Date(m+'-01T12:00:00').toLocaleDateString('en',{month:'short'})}</text>`).join('');
  return `<div class="chart-wrap"><svg class="chart-svg" viewBox="0 0 420 165" role="img" aria-label="Income and expenses for six ${scale==='year'?'years':'months'} ending ${esc(scale==='year'?month.slice(0,4):monthLabel(month))}"><title>${months.map((m,i)=>`${scale==='year'?m.slice(0,4):monthLabel(m)}: income ${money(vals[i].income)}, expenses ${money(vals[i].expense)}`).join('; ')}</title>${content}</svg></div><div class="legend"><span><i></i>Income</span><span><i class="expense"></i>Expenses</span></div>`;
}
function currentBudgetPeriod(b){
  const periods=budgetPeriodsForMonth(b,month),saved=budgetSelectedPeriods.get(`${b.id}:${month}`);if(saved&&periods.some(p=>p.start===saved))return periods.find(p=>p.start===saved);
  const reference=month===today().slice(0,7)?today():month<today().slice(0,7)?new Date(Date.UTC(Number(month.slice(0,4)),Number(month.slice(5)),0,12)).toISOString().slice(0,10):month+'-01';
  return periods.find(p=>p.start<=reference&&p.end>=reference)||periods[0]||null;
}
function budgetPeriodLabel(period){return period?period.start===period.end?dateLabel(period.start):`${dateLabel(period.start)} – ${dateLabel(period.end)}`:'';}
function budgetCard(b){const period=currentBudgetPeriod(b),used=budgetUsage(state,b,period),pct=used/b.amount*100,remaining=b.amount-used;const days=period&&period.start<=today()&&period.end>=today()?Math.round((new Date(period.end+'T12:00:00Z')-new Date(today()+'T12:00:00Z'))/86400000)+1:0;
  return `<article class="card budget-card"><a class="budget-card-link" href="#budgets/${encodeURIComponent(b.id)}" aria-label="View ${esc(b.name)} budget"></a><div class="budget-top"><strong>${esc(b.name)}</strong><button class="text-btn budget-edit" data-action="edit-budget" data-id="${esc(b.id)}">Edit</button></div><p class="budget-frequency muted small">${BUDGET_FREQUENCIES[b.frequency||'monthly']}</p><p class="budget-period-caption muted small">${period?budgetPeriodLabel(period):'Starts '+dateLabel(b.startDate)}</p><div class="budget-numbers"><strong>${money(used)}</strong><span class="muted small">of ${money(b.amount)}</span></div><div class="progress ${pct>=100?'over':pct>=80?'warning':''}" role="progressbar" aria-label="${esc(b.name)} spent" aria-valuemin="0" aria-valuemax="100" aria-valuenow="${Math.min(100,Math.round(pct))}" aria-valuetext="${pct.toFixed(1)} percent spent"><span style="width:${Math.min(100,pct)}%"></span></div><div class="budget-foot"><span class="${pct>=100?'red':''}">${remaining<0?money(-remaining)+' over':money(remaining)+' left'}</span><span>${pct.toFixed(0)}% used</span></div>${days&&remaining>0?`<p class="muted small spacer">${money(Math.floor(remaining/days))} / day · ${days} ${days===1?'day':'days'} left</p>`:''}</article>`;
}
function upcoming(){const yearly=page==='home'&&homeScale==='year',prefix=yearly?month.slice(0,4):month,last=yearly?month.slice(0,4)+'-12-31':month+'-31';const list=state.transactions.filter(t=>t.date>today()).map(t=>({...t,existing:true}));for(const r of state.rules.filter(r=>r.active)){for(let i=r.nextIndex;i<r.nextIndex+(yearly?370:100);i++){const date=occurrence(r,i);if(date>last||(r.endDate&&date>r.endDate))break;if(date>today()&&date.startsWith(prefix))list.push({...r.template,id:r.id,date,ruleId:r.id,existing:false});}}return list.filter(t=>t.date.startsWith(prefix)).sort((a,b)=>a.date.localeCompare(b.date));}
function home(){const s=summary(actual().filter(t=>t.date.startsWith(homeScale==='year'?month.slice(0,4):month)));const up=upcoming();return `<div class="home-surface">${overviewHeader('Home')}<div class="dashboard-top"><div class="hero"><div class="eyebrow">NET CASH FLOW · ${esc(homeScale==='year'?month.slice(0,4):monthLabel(month)).toUpperCase()}</div><div class="hero-amount">${money(s.income-s.expense)}</div><div class="hero-stats"><div class="hero-stat"><small><span class="dot">+</span>Income</small><strong>${money(s.income)}</strong></div><div class="hero-stat"><small><span class="dot">−</span>Expenses</small><strong>${money(s.expense)}</strong></div></div></div><div class="card chart-card"><div class="section-head"><h2>Cash flow</h2><span class="muted small">Past 6 ${homeScale==='year'?'years':'months'}</span></div>${cashChart('bar',homeScale)}</div></div>${up.length?`<button class="card scheduled" data-action="scheduled"><span class="category-icon">◷</span><span><strong>Scheduled this ${homeScale}</strong><small class="muted">${up.length} upcoming ${up.length===1?'transaction':'transactions'}</small></span><span class="scheduled-total">${money(summary(up).income-summary(up).expense)}</span></button>`:''}<section class="section"><div class="section-head"><h2>Transactions</h2><button class="text-btn" data-action="export-filtered">Export CSV</button></div>${filtersHtml()}<div id="history">${historyHtml()}</div></section></div>`;}
function overviewRows(selected=month,type='all'){
  return actual().filter(t=>!t.excluded&&(type==='all'||t.type===type)&&(overviewScale==='year'?t.date.startsWith(selected.slice(0,4)):t.date.startsWith(selected)));
}
function selectedPeriodLabel(){return overviewScale==='year'?month.slice(0,4):monthLabel(month);}
function overviewCategories(type){const rows=overviewRows(month,type);return state.categories.filter(c=>c.type===type).map(c=>({...c,total:rows.filter(t=>t.categoryId===c.id).reduce((sum,t)=>sum+t.amount,0),count:rows.filter(t=>t.categoryId===c.id).length})).filter(c=>c.count).sort((a,b)=>b.total-a.total);}
function overviewComparison(type){const total=overviewRows(month,type).reduce((sum,t)=>sum+t.amount,0),prev=overviewRows(shiftMonth(month,overviewScale==='year'?-12:-1),type).reduce((sum,t)=>sum+t.amount,0);if(!prev)return '<p class="period-comparison muted">No previous-period total to compare</p>';const delta=(total-prev)/prev*100;return `<p class="period-comparison ${type==='expense'?delta<=0?'green':'red':delta>=0?'green':'red'}">${delta>0?'↑':delta<0?'↓':'—'} ${Math.abs(delta).toFixed(1)}% <span class="muted">vs. previous ${overviewScale}</span></p>`;}
function overviewPeriodStrip(){const scale=viewScale();
  const earliest=state.transactions.reduce((min,t)=>t.date.slice(0,7)<min?t.date.slice(0,7):min,month);
  const from=scale==='year'?Math.max(1900,Math.min(Number(earliest.slice(0,4)),Number(month.slice(0,4))-3)):Math.max(0,0);
  let periods=[];
  if(scale==='year'){const last=Math.min(2200,Math.max(Number(today().slice(0,4))+2,Number(month.slice(0,4))+3));for(let y=from;y<=last;y++)periods.push(`${y}-${month.slice(5)}`);}
  else {const first=earliest<shiftMonth(month,-12)?earliest:shiftMonth(month,-12),last=shiftMonth(month,12);for(let m=first;m<=last&&m<='2200-12';m=shiftMonth(m,1))if(m>='1900-01')periods.push(m);}
  return `<div class="period-navigation"><button class="icon-btn" data-action="overview-prev" aria-label="Previous ${scale}">‹</button><div class="period-strip" aria-label="Choose ${scale}">${periods.map(m=>{const selected=scale==='year'?m.slice(0,4)===month.slice(0,4):m===month;return `<button class="period-chip ${selected?'selected':''}" data-action="overview-period" data-id="${m}" ${selected?'aria-current="date"':''}>${scale==='year'?m.slice(0,4):esc(new Date(m+'-01T12:00:00').toLocaleDateString('en-SG',{month:'short',year:'numeric'}))}</button>`;}).join('')}</div><button class="icon-btn" data-action="overview-next" aria-label="Next ${scale}">›</button></div>`;
}
function overviewHeader(title,back){const scale=viewScale();return `<div class="overview-head">${back?`<a class="icon-btn overview-back" href="${back}" aria-label="Back">‹</a>`:''}<h1>${esc(title)}</h1>${page!=='budgets'?`<div class="segmented period-toggle" aria-label="View by month or year"><button class="${scale==='month'?'selected':''}" data-action="overview-scale" data-id="month" aria-pressed="${scale==='month'}">Month</button><button class="${scale==='year'?'selected':''}" data-action="overview-scale" data-id="year" aria-pressed="${scale==='year'}">Year</button></div>`:''}</div>${overviewPeriodStrip()}`;}
function expensePie(compact=false){const categories=overviewCategories('expense'),total=categories.reduce((sum,c)=>sum+c.total,0);let start=0;const gradient=categories.map(c=>{const end=start+c.total/total*100;const value=`${c.color} ${start}% ${end}%`;start=end;return value;}).join(',');return `<div class="expense-pie ${compact?'compact':''}" role="img" aria-label="Expenses by category: ${esc(categories.map(c=>`${c.name} ${(c.total/total*100).toFixed(1)} percent`).join(', ')||'No expenses')}" style="background:${total?`conic-gradient(${gradient})`:'var(--line)'}"><div class="pie-centre"><span>${compact?'Expenses':'Categories'}</span><strong>${compact?money(total):categories.length}</strong></div></div>`;}
function periodChart(type){
  const rows=overviewRows(),year=overviewScale==='year',count=year?12:new Date(Number(month.slice(0,4)),Number(month.slice(5)),0).getDate();
  const buckets=Array.from({length:count},(_,i)=>{const selected=rows.filter(t=>Number(year?t.date.slice(5,7):t.date.slice(8))===i+1);return summary(selected);});
  const maximum=Math.max(100,...buckets.flatMap(v=>type==='income'?[v.income]:[v.income,v.expense]));
  const left=48,right=410,baseline=147,height=117,step=(right-left)/count,x=i=>left+(i+.5)*step,y=v=>baseline-height*v/maximum;
  let content=[0,.5,1].map(n=>`<line x1="${left}" y1="${baseline-height*n}" x2="420" y2="${baseline-height*n}" stroke="currentColor" opacity=".13" stroke-dasharray="4 5"/><text x="0" y="${baseline-height*n+4}" fill="currentColor" font-size="10">${n?money(Math.round(maximum*n)).replace(/\.00$/,''):'0'}</text>`).join('');
  if(type==='income'){content+=`<path d="M ${x(0)},${baseline} L ${buckets.map((v,i)=>`${x(i)},${y(v.income)}`).join(' L ')} L ${x(count-1)},${baseline} Z" fill="var(--chart-income)" opacity=".08"/><polyline points="${buckets.map((v,i)=>`${x(i)},${y(v.income)}`).join(' ')}" stroke="var(--chart-income)" stroke-width="2.5" fill="none" stroke-linejoin="round"/>`;buckets.forEach((v,i)=>{if(v.income)content+=`<circle cx="${x(i)}" cy="${y(v.income)}" r="3" fill="var(--chart-income)"/>`;});}
  else {const width=Math.min(11,step*.33);buckets.forEach((v,i)=>{content+=`<rect x="${x(i)-width-1}" y="${y(v.income)}" width="${width}" height="${height*v.income/maximum}" rx="2" fill="var(--chart-income)"/><rect x="${x(i)+1}" y="${y(v.expense)}" width="${width}" height="${height*v.expense/maximum}" rx="2" fill="var(--chart-expense)"/>`;});}
  buckets.forEach((v,i)=>{if(year||i===0||i===count-1||(i+1)%7===0)content+=`<text x="${x(i)}" y="170" text-anchor="middle" fill="currentColor" font-size="${year?9:11}">${year?new Date(2026,i,1).toLocaleDateString('en',{month:'short'}):i+1}</text>`;});
  return `<svg class="chart-svg period-chart" viewBox="0 0 430 180" role="img" aria-label="${type==='income'?'Income line chart':'Inflow and outflow bar chart'} for ${selectedPeriodLabel()}"><title>${buckets.map((v,i)=>`${year?'Month':'Day'} ${i+1}: income ${money(v.income)}, expenses ${money(v.expense)}`).join('; ')}</title>${content}</svg>${type==='income'?'<div class="legend"><span><i></i>Income</span></div>':'<div class="legend"><span><i></i>Inflow</span><span><i class="expense"></i>Outflow</span></div>'}`;
}
function overviewCategoryRows(type,baseRoute){const categories=overviewCategories(type),total=categories.reduce((sum,c)=>sum+c.total,0);return categories.length?`<div class="card category-detail-list">${categories.map(c=>`<a href="${baseRoute||'#overview/'+(type==='expense'?'expenses':'income')}/category/${encodeURIComponent(c.id)}" class="category-detail-row">${categoryIcon(c)}<span class="category-detail-copy"><strong>${esc(c.name)}</strong><small>${c.count} ${c.count===1?'transaction':'transactions'}</small></span><span class="category-detail-amount"><strong>${type==='expense'?'−':'+'}${money(c.total)}</strong><small>${(c.total/total*100).toFixed(1)}%</small></span><span class="row-chevron">›</span></a>`).join('')}</div>`:empty('No transactions this period','Choose another '+overviewScale+' or add a transaction.');}
function overview(){
  const route=location.hash.slice(1).split('/'),detail=route[1],flowType=detail==='cash-flow'&&['expense','income'].includes(route[2])?route[2]:null,categoryId=flowType&&route[3]==='category'?decodeURIComponent(route[4]||''):route[2]==='category'?decodeURIComponent(route[3]||''):null;
  const totals=summary(overviewRows()),label=selectedPeriodLabel();
  if(categoryId&&(['expenses','income'].includes(detail)||flowType)&&cat(categoryId)){const c=cat(categoryId),type=flowType||(detail==='expenses'?'expense':'income'),rows=overviewRows(month,type).filter(t=>t.categoryId===categoryId);return `<div class="overview-surface">${overviewHeader(c.name,`#overview/${detail}`)}<div class="category-period-total">${categoryIcon(c)}<div><span class="muted small">${esc(label)}</span><strong>${type==='expense'?'−':'+'}${money(rows.reduce((sum,t)=>sum+t.amount,0))}</strong><span class="muted small">${rows.length} ${rows.length===1?'transaction':'transactions'}</span></div></div>${historyHtml(rows)}</div>`;}
  if(detail==='expenses')return `<div class="overview-surface">${overviewHeader('Expenses','#overview')}<div class="detail-summary"><div class="overview-total">−${money(totals.expense)}</div>${overviewComparison('expense')}${expensePie()}</div>${overviewCategoryRows('expense')}</div>`;
  if(detail==='cash-flow')return `<div class="overview-surface">${overviewHeader('Cash flow','#overview')}<div class="detail-summary"><div class="overview-total">${money(totals.income-totals.expense)}</div><p class="muted small">Net cash flow · ${esc(label)}</p></div><div class="card overview-detail-chart">${periodChart('cash-flow')}<div class="cash-flow-totals"><div><span>Inflow</span><strong>+${money(totals.income)}</strong></div><div><span>Outflow</span><strong>−${money(totals.expense)}</strong></div></div></div><h2 class="detail-list-title">Top inflow categories</h2>${overviewCategoryRows('income','#overview/cash-flow/income')}<h2 class="detail-list-title">Top outflow categories</h2>${overviewCategoryRows('expense','#overview/cash-flow/expense')}</div>`;
  if(detail==='income')return `<div class="overview-surface">${overviewHeader('Income','#overview')}<div class="detail-summary"><div class="overview-total">+${money(totals.income)}</div>${overviewComparison('income')}</div><div class="card overview-detail-chart">${periodChart('income')}</div><h2 class="detail-list-title">Income categories</h2>${overviewCategoryRows('income')}</div>`;
  const categories=overviewCategories('expense');
  return `<div class="overview-surface">${overviewHeader('Overview')}<div class="overview-card-stack"><a class="card overview-card" href="#overview/expenses"><div class="section-head"><h2>Expenses</h2><span class="row-chevron" aria-hidden="true">›</span></div><div class="overview-card-total">${money(totals.expense)}</div>${overviewComparison('expense')}<div class="expenses-preview">${expensePie(true)}<div class="preview-categories">${categories.slice(0,3).map(c=>`<div><i style="background:${c.color}"></i><span>${esc(c.name)}</span><strong>${(c.total/totals.expense*100).toFixed(1)}%</strong></div>`).join('')||'<p class="muted small">No expenses this '+overviewScale+'.</p>'}</div></div></a><a class="card overview-card" href="#overview/cash-flow"><div class="section-head"><h2>Cash flow</h2><span class="row-chevron" aria-hidden="true">›</span></div><div class="overview-card-total">${money(totals.income-totals.expense)}</div><p class="muted small">Net · ${esc(label)}</p>${periodChart('cash-flow')}</a><a class="card overview-card" href="#overview/income"><div class="section-head"><h2>Income</h2><span class="row-chevron" aria-hidden="true">›</span></div><div class="overview-card-total">${money(totals.income)}</div>${overviewComparison('income')}${periodChart('income')}</a></div></div>`;
}
function changeOverviewPeriod(step){const next=shiftMonth(month,step*(viewScale()==='year'?12:1));if(next<'1900-01'||next>'2200-12')return;month=next;const y=window.scrollY;render();window.scrollTo(0,y);}
function centreOverviewPeriod(){const strip=$('.period-strip'),selected=$('.period-chip.selected');if(strip&&selected)strip.scrollLeft=selected.offsetLeft-(strip.clientWidth-selected.clientWidth)/2;}
function budgetPeriodChart(b,periods,selected){
  const values=periods.map(p=>budgetUsage(state,b,p)),maximum=Math.max(100,b.amount,...values)*1.15,left=58,right=420,baseline=152,height=115,step=(right-left)/Math.max(1,periods.length),lineY=baseline-height*b.amount/maximum;
  let chart=[0,.5,1].map(n=>`<line x1="${left}" y1="${baseline-height*n}" x2="${right}" y2="${baseline-height*n}" stroke="currentColor" opacity=".12"/><text x="0" y="${baseline-height*n+4}" fill="currentColor" font-size="10">${money(Math.round(maximum*n)).replace(/\.00$/,'')}</text>`).join('');
  chart+=periods.map((p,i)=>{const width=Math.min(44,step*.65),x=left+(i+.5)*step;return `<a href="#budgets/${encodeURIComponent(b.id)}" data-action="budget-period" data-id="${esc(b.id)}" data-start="${p.start}" aria-label="${esc(budgetPeriodLabel(p))}: spent ${money(values[i])}"><rect x="${x-width/2}" y="${baseline-height*values[i]/maximum}" width="${width}" height="${height*values[i]/maximum}" rx="4" fill="${values[i]>b.amount?'var(--red)':p.start===selected?.start?'var(--chart-income)':'var(--chart-expense)'}"/><rect x="${x-step/2}" y="26" width="${step}" height="140" fill="transparent"/></a>${periods.length<=7||i===0||i===periods.length-1||(i+1)%7===0?`<text x="${x}" y="176" text-anchor="middle" fill="currentColor" font-size="10">${periods.length===1?BUDGET_FREQUENCIES[b.frequency||'monthly']:p.start.slice(8)+'/'+p.start.slice(5,7)}</text>`:''}`;}).join('');
  chart+=`<line class="budget-limit-line" x1="${left}" x2="${right}" y1="${lineY}" y2="${lineY}" stroke="var(--budget-line)" stroke-width="2" stroke-dasharray="6 4"/><text x="${right}" y="${lineY-7}" text-anchor="end" fill="var(--budget-line-text)" font-size="11" font-weight="600">Budget ${money(b.amount)}</text>`;
  return `<svg class="chart-svg budget-chart" viewBox="0 0 440 190" role="img" aria-label="Spending by budget period with limit ${money(b.amount)}"><title>${periods.map((p,i)=>`${budgetPeriodLabel(p)}: ${money(values[i])}; limit ${money(b.amount)}`).join('; ')||'No budget periods in this month'}</title>${chart}</svg><div class="legend"><span><i></i>Spent</span><span><i class="budget-limit-dot"></i>Budget limit</span></div>`;
}
function budgetDetail(b){const periods=budgetPeriodsForMonth(b,month),selected=currentBudgetPeriod(b),rows=budgetTransactions(state,b,selected),used=budgetUsage(state,b,selected),remaining=b.amount-used;const categories=state.categories.filter(c=>c.type==='expense').map(c=>({...c,total:rows.filter(t=>t.categoryId===c.id).reduce((sum,t)=>sum+t.amount,0),count:rows.filter(t=>t.categoryId===c.id).length})).filter(c=>c.count).sort((a,b)=>b.total-a.total);
  return `<div class="budget-surface">${overviewHeader(b.name,'#budgets')}<div class="section-head"><span class="muted small">${BUDGET_FREQUENCIES[b.frequency||'monthly']} · ${money(b.amount)} per period</span><button class="text-btn" data-action="edit-budget" data-id="${esc(b.id)}">Edit budget</button></div>${periods.length>1?`<div class="budget-cycle-selector" aria-label="Choose budget period">${periods.map(p=>`<button class="chip ${p.start===selected?.start?'selected':''}" data-action="budget-period" data-id="${esc(b.id)}" data-start="${p.start}" aria-pressed="${p.start===selected?.start}">${p.start===p.end?dateLabel(p.start):dateLabel(p.start)+' – '+dateLabel(p.end)}</button>`).join('')}</div>`:''}<div class="detail-summary"><p class="muted small" id="budget-selected-period">${selected?budgetPeriodLabel(selected):'Starts '+dateLabel(b.startDate)}</p><div class="overview-total budget-used">${money(used)}</div><p class="${remaining<0?'red':'muted'} small">${remaining<0?money(-remaining)+' over budget':money(remaining)+' remaining'} · ${rows.length} ${rows.length===1?'transaction':'transactions'}</p></div><div class="card overview-detail-chart">${budgetPeriodChart(b,periods,selected)}${['weekly','fortnightly','yearly'].includes(b.frequency)?'<p class="muted small spacer">Each bar covers a complete budget period, including dates outside this month.</p>':''}</div><h2 class="detail-list-title">Expense categories</h2>${categories.length?`<div class="card category-detail-list">${categories.map(c=>`<div class="category-detail-row">${categoryIcon(c)}<span class="category-detail-copy"><strong>${esc(c.name)}</strong><small>${c.count} ${c.count===1?'transaction':'transactions'}</small></span><span class="category-detail-amount"><strong>${money(c.total)}</strong><small>${(c.total/used*100).toFixed(1)}%</small></span></div>`).join('')}</div>`:empty('No spending in this period','Expenses in the included categories will appear here.')}<h2 class="detail-list-title">Transactions</h2>${historyHtml(rows)}</div>`;
}
function budgets(){const id=decodeURIComponent(location.hash.slice(1).split('/')[1]||''),b=state.budgets.find(b=>b.id===id);if(b)return budgetDetail(b);const over=state.budgets.filter(b=>currentBudgetPeriod(b)&&budgetUsage(state,b,currentBudgetPeriod(b))>=b.amount);
  return `<div class="budget-surface">${overviewHeader('Budgets')}<div class="section-head"><p class="muted small">Limits apply to each budget’s recurring period.</p><button class="text-btn" data-action="add-budget">+ New budget</button></div>${over.length?`<div class="alert">${over.map(b=>esc(b.name)).join(', ')}: budget limit reached.</div>`:''}${state.budgets.length?`<div class="budget-grid">${state.budgets.map(budgetCard).join('')}</div>`:`<div class="card">${empty('Give your spending a plan','Set a limit for all expenses or specific categories.','add-budget','Create a budget')}</div>`}</div>`;
}
function settings(){return `${head('Your preferences','SETTINGS')}<div class="overview-layout"><div><div class="card settings-group"><button class="setting-row" data-action="manage-categories"><span><strong>Categories</strong><small>Organise income and expenses</small></span><span class="muted">${state.categories.filter(c=>!c.archived).length} ›</span></button><button class="setting-row" data-action="manage-labels"><span><strong>Labels</strong><small>Add context to your transactions</small></span><span class="muted">${state.labels.length} ›</span></button><fieldset class="default-entry-setting"><legend>Open ‘Add transaction’ by default</legend><p class="muted small">Choose how to start when opening the app</p><div class="default-entry-options">${[['none','None'],['manual','Manual'],['dictation','Dictation']].map(([value,label])=>`<label><input type="radio" name="default-entry-mode" value="${value}" ${state.settings.defaultEntryMode===value?'checked':''}><span>${label}</span></label>`).join('')}</div></fieldset><button class="setting-row" data-action="manage-rules"><span><strong>Recurring transactions</strong><small>Manage automatic entries</small></span><span class="muted">${state.rules.filter(r=>r.active).length} active ›</span></button><div class="appearance-setting"><strong>Appearance</strong><p class="muted small">Choose your colour scheme</p><div class="theme-choices" aria-label="Colour scheme">${[['system','System'],['light','Light'],['dark','Dark'],['colourful','Colourful'],['cheerful','Cheerful'],['pastel','Pastel']].map(([key,label])=>`<button class="theme-choice theme-preview-${key} ${state.settings.theme===key?'selected':''}" data-action="choose-theme" data-id="${key}" aria-pressed="${state.settings.theme===key}"><span class="theme-swatches" aria-hidden="true"><i></i><i></i><i></i></span><span>${label}</span><span class="theme-tick" aria-hidden="true">${state.settings.theme===key?'✓':''}</span></button>`).join('')}</div></div></div><div class="card settings-group"><div class="section-head"><h2>Your data</h2><span class="local-badge">◇ On this device</span></div><button class="setting-row" data-action="export-all"><span><strong>Export transactions</strong><small>Download a CSV for your spreadsheet</small></span><span class="muted">↓</span></button><button class="setting-row" data-action="backup"><span><strong>Back up everything</strong><small>Transactions, budgets, categories and settings</small></span><span class="muted">↓</span></button><button class="setting-row" data-action="restore"><span><strong>Restore a backup</strong><small>Replace current data with a JSON backup</small></span><span class="muted">↑</span></button><button class="setting-row" data-action="reset"><span><strong class="red">Reset all data</strong><small>Export a backup before clearing your records</small></span><span class="muted">×</span></button></div></div><div class="settings-info"><h2 class="spacer">A personal space</h2><p class="spacer">${state.transactions.length} transactions · SGD only</p><p>Your records are saved in this browser on this device. They are never sent to GitHub or any server.</p><p>Clearing browser data can remove your records. Download a JSON backup regularly; you can restore it on another device. CSV exports contain transactions only.</p><p>Recurring entries are added when you open the app. Upcoming entries stay separate from your actual spending.</p><h2 class="spacer">Keep it close</h2><p class="spacer">${isNativeApp()?'This is the installed Android version. Restore a JSON backup to bring over records from the web app.':'On iPhone, open in Safari, tap Share, then Add to Home Screen. On Android, use your browser’s Install app or Add to Home screen option.'}</p><p>${isNativeApp()?'The Android app includes everything needed to work offline. Use the Android share sheet to save your exports and backups.':'The app works offline after your first visit.'}</p><p>Everyday · version 1.8</p></div></div>`;}
function render(){const route=location.hash.slice(1).split('/')[0];page=['home','overview','budgets','settings'].includes(route)?route:'home';$('.bottom-nav').innerHTML=[['home','Home'],['overview','Overview'],['budgets','Budgets'],['settings','Settings']].map(([id,name])=>`<a class="nav-link ${page===id?'active':''}" href="#${id}" ${page===id?'aria-current="page"':''}>${svg(id)}${name}</a>`).join('');$('#app').innerHTML=(blocked?'<div class="alert">Saved data could not be read. Your original data has been preserved. Use Settings to download the original data, restore a backup or reset.</div>':'')+({home,overview,budgets,settings}[page]());if(['home','overview','budgets'].includes(page))centreOverviewPeriod();}
function openDialog(title,body){dictation.cancel();$('#editor').classList.remove('transaction-editor');$('#editor').style.removeProperty('--entry-height');$('#dialog-content').innerHTML=`<div class="dialog-head"><h2 id="dialog-title">${title}</h2><button class="icon-btn" data-action="close" aria-label="Close dialog">×</button></div><div class="dialog-body">${body}</div>`;if(!$('#editor').open)$('#editor').showModal();}
function closeDialog(){dictation.cancel();$('#editor').close();}
function error(message){const el=$('#form-error');if(el){el.textContent=message;el.scrollIntoView({block:'nearest'});}else toast(message);}
function labelChips(selected){return `<div class="chips" id="label-chips">${state.labels.map(l=>`<button type="button" class="chip ${selected.includes(l.id)?'selected':''}" aria-pressed="${selected.includes(l.id)}" data-action="toggle-chip" data-id="${esc(l.id)}">${esc(l.name)}</button>`).join('')}<button type="button" class="chip" data-action="quick-label">+ Label</button></div>`;}
function categoryPicker(type,selected){return state.categories.filter(c=>c.type===type&&(!c.archived||c.id===selected)).map(c=>`<button type="button" class="category-choice ${c.id===selected?'selected':''}" aria-pressed="${c.id===selected}" data-action="select-category" data-id="${esc(c.id)}">${categoryIcon(c)}<span>${esc(c.name)}</span></button>`).join('');}
function transactionPanel(mode){
  const form=$('#transaction-form');if(!form)return;
  form.dataset.panel=mode;
  for(const [selector,key] of [['#category-panel','categories'],['#calculator-slot','keypad'],['#transaction-options','options']])$(selector).hidden=mode!==key;
  const c=cat($('#category-id').value);
  $('#selected-category').innerHTML=c?`${categoryIcon(c)}<span>${esc(c.name)}</span><span class="category-chevron">⌄</span>`:'<span class="category-icon">◈</span><span>Select category</span><span class="category-chevron">⌄</span>';
  $('#selected-category').setAttribute('aria-expanded',String(mode==='categories'));
}
function transactionDialog(id,draft=null){
  const t=id?state.transactions.find(t=>t.id===id):null;if(id&&!t)return;
  const entry=t||draft;const type=entry?.type||'expense';
  openDialog(t?'Edit transaction':'Add transaction',`<form id="transaction-form" data-id="${esc(id||'')}">
    <input type="hidden" id="transaction-type" value="${type}"><input type="hidden" id="category-id" value="${esc(entry?.categoryId||'')}">
    <div class="entry-hero"><div class="entry-category-bar"><button type="button" id="selected-category" data-action="choose-category" aria-label="Choose category"></button>${!t?`<button type="button" class="dictate-button" id="dictate-transaction" data-action="dictate" aria-label="Dictate transaction" aria-pressed="false" ${speechAvailable()?'':'disabled'} title="Dictate a category and amount; say Income for income"><svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.8" stroke-linecap="round" aria-hidden="true"><rect x="9" y="2" width="6" height="12" rx="3"/><path d="M5 10v2a7 7 0 0 0 14 0v-2M12 19v3M8 22h8"/></svg></button>`:''}</div><div class="amount-field"><input id="amount" aria-label="Amount or calculation in SGD" inputmode="none" autocomplete="off" placeholder="0" value="${entry?.amount?(entry.amount/100).toFixed(2):''}" required><span>SGD</span><button type="button" class="calculate-button" data-action="calc-key" data-id="=" aria-label="Calculate amount">=</button></div></div>
    <div class="entry-note"><textarea id="description" aria-label="Transaction description" maxlength="1000" placeholder="Describe your transaction" rows="1">${esc(entry?.description||'')}</textarea>${labelChips(entry?.labelIds||[])}</div>
    <div class="entry-date-row"><label class="date-pill"><span aria-hidden="true">▦</span><input id="transaction-date" aria-label="Transaction date" type="date" min="1900-01-01" max="2200-12-31" value="${entry?.date||today()}" required></label>${t?.ruleId?'<span class="repeat-pill recurring-note">↻ Recurring entry</span>':`<label class="repeat-pill"><span aria-hidden="true">↻</span><select id="frequency" aria-label="Repeat frequency">${Object.entries(FREQUENCIES).map(([k,v])=>`<option value="${k}">${v}</option>`).join('')}</select></label>`}</div>
    <div class="entry-panel"><section id="category-panel"><h3>Select category</h3><div class="category-picker" id="category-picker">${categoryPicker(type,entry?.categoryId)}</div></section><div id="calculator-slot" hidden><div class="keypad">${['1','2','3','÷','4','5','6','×','7','8','9','−','.','0','⌫','+'].map(k=>`<button type="button" data-action="calc-key" data-id="${k}" aria-label="${k==='⌫'?'Backspace':k}">${k}</button>`).join('')}</div></div><section id="transaction-options" hidden><h3>Transaction options</h3><label class="checkbox"><input id="excluded" type="checkbox" ${t?.excluded?'checked':''}>Exclude from overview and budgets</label>${t?.ruleId?'<p class="muted small spacer">Changes apply to this entry only. Manage future entries in Settings.</p>':''}<button type="button" class="text-btn" data-action="calc-key" data-id="C">Clear amount</button>${t?`<button class="btn danger full spacer" type="button" data-action="delete-transaction" data-id="${esc(t.id)}">Delete transaction</button>`:''}<button type="button" class="btn secondary full spacer" data-action="entry-done">Done</button></section></div>
    <div class="entry-footer">${!t?`<p class="dictation-status muted small" id="dictation-status" role="status">${speechAvailable()?'Tap mic: “Groceries $15” · saves automatically.':'Dictation unavailable in this browser; use manual entry.'}</p>`:''}${draft?'<p class="muted small voice-review">Review before saving. Check this app contains your usual records.</p>':''}<p class="form-error" id="form-error" role="alert"></p><div class="segmented" id="transaction-types"><button type="button" class="${type==='expense'?'selected':''}" data-action="transaction-type" data-id="expense">Expenses</button><button type="button" class="${type==='income'?'selected':''}" data-action="transaction-type" data-id="income">Income</button></div><button class="btn full" type="submit">${t?'Save changes':'Add Transaction'}</button></div>
  </form>`);
  $('#editor').classList.add('transaction-editor');
  $('.dialog-head').innerHTML=`<button class="icon-btn" data-action="close" aria-label="Close dialog">×</button><h2 id="dialog-title">${t?'Edit transaction':draft?'Review transaction':'Add transaction'}</h2><button class="icon-btn" data-action="entry-options" aria-label="Transaction options" aria-expanded="false">···</button>`;
  transactionPanel(entry?.categoryId?'keypad':'categories');
}
function openDefaultTransaction(){
  if(blocked||document.hidden||state.settings.defaultEntryMode==='none'||$('#editor').open)return;
  transactionDialog();
  if(state.settings.defaultEntryMode==='dictation'&&speechAvailable())dictation.start();
}
function consumeVoiceEntry(){
  if(!location.hash.startsWith('#add?'))return false;
  const link=location.href;
  history.replaceState(null,'',location.pathname+location.search+'#home');render();
  try{if(blocked)throw Error('Restore or reset unreadable data before adding a transaction.');transactionDialog(null,parseVoiceLink(link,state.categories,location.href));}catch(e){toast(e.message);}
  return true;
}
function readTemplate(){if(/[+×÷−*/()\-]|^\.|\.$/.test($('#amount').value))$('#amount').value=evaluateExpression($('#amount').value);const categoryId=$('#category-id').value;if(!categoryId)throw Error('Choose a category.');return {type:$('#transaction-type').value,amount:parseAmount($('#amount').value),categoryId,labelIds:[...document.querySelectorAll('#label-chips .chip.selected')].map(b=>b.dataset.id),description:$('#description').value.trim(),excluded:$('#excluded').checked};}
function saveTransaction(form,dictated=false){try{const template=readTemplate();const date=$('#transaction-date').value;if(!validDate(date))throw Error('Choose a valid date.');const id=form.dataset.id;const frequency=$('#frequency')?.value||'none';let savedId;const ok=commit(next=>{let t=next.transactions.find(t=>t.id===id);if(t){if(t.date!==date)delete t.timestamp;Object.assign(t,template,{date});}else {t={id:uid(),...template,date};next.transactions.push(t);}savedId=t.id;if(frequency!=='none'){const rule={id:uid(),template,startDate:date,frequency,nextIndex:1,active:true,endDate:null};t.ruleId=rule.id;next.rules.push(rule);processRules(next);}});if(ok){closeDialog();const saved=state.transactions.find(t=>t.id===savedId);if(dictated)toast(`Added ${money(saved.amount)} · ${cat(saved.categoryId).name} · ${saved.type==='expense'?'Expense':'Income'}`,{id:saved.id,snapshot:JSON.stringify(saved)});else toast('Transaction saved.');}}catch(e){error(e.message);}}
function applyDictation(text,uncertain){
  const form=$('#transaction-form');if(!form||!$('#editor').open)return;
  const parsed=parseDictation(text,state.categories),draft=parsed.draft;
  if(draft.type){$('#transaction-type').value=draft.type;$('#category-id').value=draft.categoryId;$('#category-picker').innerHTML=categoryPicker(draft.type,draft.categoryId);document.querySelectorAll('#transaction-types button').forEach(b=>b.classList.toggle('selected',b.dataset.id===draft.type));transactionPanel(draft.categoryId?'keypad':'categories');}
  if(draft.amount!==null)$('#amount').value=(draft.amount/100).toFixed(2);else if(draft.type)$('#amount').value='';
  $('#dictation-status').textContent=`Heard: “${text}”. ${parsed.message||'Check the details.'}`;
  if(!parsed.valid)return;
  // Recurring/excluded entries and low-confidence speech need the normal Save tap.
  if(uncertain||form.dataset.id||($('#frequency')?.value||'none')!=='none'||$('#excluded').checked){$('#dictation-status').textContent=`Heard: “${text}”. Review and tap Add Transaction to save.`;return;}
  saveTransaction(form,true);
}

function budgetDialog(id){const b=id?state.budgets.find(b=>b.id===id):null;openDialog(b?'Edit budget':'New budget',`<form id="budget-form" data-id="${esc(id||'')}"><div class="notice">The limit applies to each recurring period. Weekly and bi-weekly periods start on your chosen date; monthly and yearly periods follow the calendar.</div><label class="field">Budget name<input id="budget-name" maxlength="80" value="${esc(b?.name||'')}" placeholder="e.g. Monthly essentials" required></label><label class="field">Limit per period (SGD)<input id="budget-amount" inputmode="decimal" value="${b?(b.amount/100).toFixed(2):''}" placeholder="500.00" required></label><label class="field">Recurrence<select id="budget-frequency">${Object.entries(BUDGET_FREQUENCIES).map(([key,label])=>`<option value="${key}" ${(b?.frequency||'monthly')===key?'selected':''}>${label}</option>`).join('')}</select></label><label class="field">Start date<input id="budget-start" type="date" min="1900-01-01" max="2200-12-31" value="${b?.startDate||month+'-01'}" required></label><label class="field">Included categories</label><p class="muted small spacer">Leave all unselected to include every expense category.</p><div class="chips" id="budget-categories">${state.categories.filter(c=>c.type==='expense'&&(!c.archived||b?.categoryIds.includes(c.id))).map(c=>`<button type="button" class="chip ${b?.categoryIds.includes(c.id)?'selected':''}" aria-pressed="${!!b?.categoryIds.includes(c.id)}" data-action="toggle-chip" data-id="${esc(c.id)}">${esc(c.icon)} ${esc(c.name)}</button>`).join('')}</div><p class="form-error" id="form-error" role="alert"></p><div class="btn-row">${b?`<button type="button" class="btn danger" data-action="delete-budget" data-id="${esc(id)}">Delete</button>`:''}<button class="btn" type="submit">Save budget</button></div></form>`);}
function manageCategories(){openDialog('Categories',`<button class="btn full secondary" data-action="new-category">+ Add category</button>${state.categories.map(c=>`<div class="manage-row ${c.archived?'archived':''}">${categoryIcon(c)}<div class="copy"><strong>${esc(c.name)}</strong><small>${c.type==='expense'?'Expense':'Income'}${c.archived?' · Archived':''}</small></div><button class="text-btn" data-action="edit-category" data-id="${esc(c.id)}">Edit</button><button class="text-btn" data-action="archive-category" data-id="${esc(c.id)}">${c.archived?'Restore':'Archive'}</button></div>`).join('')}<p class="muted small spacer">Archiving hides a category from new entries. Existing records stay intact.</p>`);}
function categoryDialog(id){const c=id?cat(id):null;openDialog(c?'Edit category':'New category',`<form id="category-form" data-id="${esc(id||'')}"><label class="field">Name<input id="category-name" maxlength="80" value="${esc(c?.name||'')}" required></label><div class="field-row"><label class="field">Icon or emoji<input id="category-icon" maxlength="20" value="${esc(c?.icon||'◈')}" required></label><label class="field">Colour<input id="category-color" type="color" value="${c?.color||'#2563eb'}"></label></div><label class="field">Type<select id="category-type" ${c?'disabled':''}><option value="expense">Expense</option><option value="income" ${c?.type==='income'?'selected':''}>Income</option></select></label><p class="form-error" id="form-error" role="alert"></p><div class="btn-row"><button class="btn" type="submit">Save category</button></div></form>`);}
function manageLabels(){openDialog('Labels',`<button class="btn secondary full" data-action="new-label">+ Add label</button>${state.labels.length?state.labels.map(l=>`<div class="manage-row"><div class="copy"><strong>${esc(l.name)}</strong></div><button class="text-btn" data-action="edit-label" data-id="${esc(l.id)}">Rename</button><button class="text-btn red" data-action="delete-label" data-id="${esc(l.id)}">Delete</button></div>`).join(''):empty('A little extra context','Use labels like Needs, Wants or Coffee to group transactions across categories.')}`);}
function labelDialog(id){const l=state.labels.find(l=>l.id===id);openDialog(l?'Rename label':'New label',`<form id="label-form" data-id="${esc(id||'')}"><label class="field">Label name<input id="label-name" maxlength="60" value="${esc(l?.name||'')}" required></label><p class="form-error" id="form-error" role="alert"></p><div class="btn-row"><button class="btn" type="submit">Save label</button></div></form>`);}
function manageRules(){openDialog('Recurring transactions',`<div class="notice">Due entries are added when you open the app. Pause a rule to stop future entries; existing transactions stay intact.</div>${state.rules.length?state.rules.map(r=>`<div class="manage-row">${categoryIcon(cat(r.template.categoryId))}<div class="copy"><strong>${esc(r.template.description||cat(r.template.categoryId).name)}</strong><small>${money(r.template.amount)} · ${FREQUENCIES[r.frequency]}<br>${r.active?'Next: '+dateLabel(occurrence(r,r.nextIndex)):'Paused'}</small></div><button class="text-btn" data-action="edit-rule" data-id="${esc(r.id)}">Edit</button><button class="text-btn" data-action="toggle-rule" data-id="${esc(r.id)}">${r.active?'Pause':'Resume'}</button></div>`).join(''):empty('No recurring entries','Set a repeat frequency when adding a transaction.','add','Add transaction')}`);}
function ruleDialog(id){const r=state.rules.find(r=>r.id===id);openDialog('Edit recurring transaction',`<form id="rule-form" data-id="${esc(id)}"><div class="notice">Changes apply to future entries. Existing transactions are preserved. Resuming adds any due entries since the last occurrence.</div><label class="field">Amount (SGD)<input id="rule-amount" inputmode="decimal" value="${(r.template.amount/100).toFixed(2)}" required></label><label class="field">Description<input id="rule-description" maxlength="1000" value="${esc(r.template.description)}"></label><label class="field">Repeat<select id="rule-frequency">${Object.entries(FREQUENCIES).filter(([k])=>k!=='none').map(([k,v])=>`<option value="${k}" ${r.frequency===k?'selected':''}>${v}</option>`).join('')}</select></label><label class="field">Next date<input id="rule-date" type="date" min="1900-01-01" max="2200-12-31" value="${occurrence(r,r.nextIndex)}" required></label><label class="field">End date (optional)<input id="rule-end" type="date" min="1900-01-01" max="2200-12-31" value="${r.endDate||''}"></label><p class="form-error" id="form-error" role="alert"></p><div class="btn-row"><button type="button" class="btn danger" data-action="remove-rule" data-id="${esc(id)}">Remove rule</button><button class="btn" type="submit">Save rule</button></div></form>`);}
function scheduledDialog(){const up=upcoming();openDialog('Scheduled · '+esc(viewScale()==='year'?month.slice(0,4):monthLabel(month)),`${up.length?up.map(t=>`<div class="manage-row">${categoryIcon(cat(t.categoryId))}<div class="copy"><strong>${esc(t.description||cat(t.categoryId).name)}</strong><small>${dateLabel(t.date)} · ${t.type==='expense'?'−':'+'}${money(t.amount)}</small></div><button class="text-btn" data-action="${t.existing?'edit-transaction':'edit-rule'}" data-id="${esc(t.id)}">Edit</button></div>`).join(''):empty('Nothing scheduled','Upcoming transactions will appear here.')}<p class="muted small spacer">Upcoming entries are excluded from actual spending until their date arrives.</p>`);}
function download(content,name,type){exportFile(content,name,type).catch(()=>toast('Export could not be completed. Please try again.'));}
function backup(){if(blocked){try{download(localStorage.getItem(STORAGE_KEY)||'{}',`everyday-original-data-${today()}.json`,'application/json');}catch{toast('Browser storage is unavailable.');}}else download(JSON.stringify(state,null,2),`everyday-backup-${today()}.json`,'application/json');}
function calculator(){transactionPanel('keypad');}
function evaluateExpression(value){const s=value.replaceAll('×','*').replaceAll('÷','/').replaceAll('−','-').replaceAll(' ','');if(s.length>200||!/^[\d.+*/()\-]+$/.test(s))throw Error('Enter a valid calculation.');const tokens=s.match(/\d+(?:\.\d*)?|\.\d+|[+*/()\-]/g);if(!tokens||tokens.join('')!==s)throw Error('Enter a valid calculation.');let i=0;function atom(){if(tokens[i]==='-'){i++;return -atom();}if(tokens[i]==='+'){i++;return atom();}if(tokens[i]==='('){i++;const n=sum();if(tokens[i++]!==')')throw Error('Check your brackets.');return n;}const token=tokens[i++];if(!token||!/^(\d|\.)/.test(token))throw Error('Enter a valid calculation.');return Number(token);}function product(){let n=atom();while(['*','/'].includes(tokens[i])){const op=tokens[i++],rhs=atom();n=op==='*'?n*rhs:n/rhs;}return n;}function sum(){let n=product();while(['+','-'].includes(tokens[i])){const op=tokens[i++],rhs=product();n=op==='+'?n+rhs:n-rhs;}return n;}const result=sum();if(i!==tokens.length||!Number.isFinite(result)||result<=0)throw Error('The result must be a positive amount.');return result.toFixed(2);}

document.addEventListener('click',e=>{const el=e.target.closest('[data-action]');if(!el)return;const a=el.dataset.action,id=el.dataset.id;if(a!=='dictate')dictation.cancel();
  if(a==='dictate'){if(blocked){error('Restore or reset unreadable data before adding a transaction.');return;}if(dictation.isListening())dictation.stop();else dictation.start();}
  else if(a==='undo-dictation'){const undo=dictationUndo;if(!undo)return;const current=state.transactions.find(t=>t.id===undo.id);if(!current||JSON.stringify(current)!==undo.snapshot){toast('This transaction changed. Open it to review or delete it.');return;}if(commit(s=>s.transactions=s.transactions.filter(t=>t.id!==undo.id)))toast('Dictated transaction removed.');}
  else if(a==='close')closeDialog();
  else if(a==='add')transactionDialog();
  else if(a==='edit-transaction')transactionDialog(id);
  else if(a==='prev-month'||a==='next-month'){const next=shiftMonth(month,a==='prev-month'?-1:1);if(next>='1900-01'&&next<='2200-12'){month=next;render();}}
  else if(a==='toggle-filters'){showFilters=!showFilters;render();}
  else if(a==='clear-filters'){filter={query:'',type:'all',category:'all',label:'all',from:'',to:''};render();}
  else if(a==='choose-theme'){if(['system','light','dark','colourful','cheerful','pastel'].includes(id))commit(s=>s.settings.theme=id);}
  else if(a==='overview-scale'){if(page==='home')homeScale=id==='year'?'year':'month';else overviewScale=id==='year'?'year':'month';render();}
  else if(a==='overview-period'){month=id;render();}
  else if(a==='overview-prev'||a==='overview-next'){changeOverviewPeriod(a==='overview-prev'?-1:1);}
  else if(a==='toggle-chip'){el.classList.toggle('selected');el.setAttribute('aria-pressed',String(el.classList.contains('selected')));}
  else if(a==='select-category'){$('#category-id').value=id;$('#category-picker').innerHTML=categoryPicker($('#transaction-type').value,id);transactionPanel('keypad');}
  else if(a==='transaction-type'){$('#transaction-type').value=id;$('#category-id').value='';$('#category-picker').innerHTML=categoryPicker(id,'');document.querySelectorAll('#transaction-types button').forEach(b=>b.classList.toggle('selected',b.dataset.id===id));transactionPanel('categories');}
  else if(a==='quick-label'){const name=prompt('New label name');if(name?.trim()){const clean=name.trim().slice(0,60);let l=state.labels.find(l=>l.name.toLowerCase()===clean.toLowerCase());if(!l){l={id:uid(),name:clean};if(!commit(s=>s.labels.push(l)))return;}const selected=[...document.querySelectorAll('#label-chips .selected')].map(b=>b.dataset.id);$('#label-chips').outerHTML=labelChips([...selected,l.id]);}}
  else if(a==='calculator')calculator();
  else if(a==='choose-category'){transactionPanel($('#transaction-form').dataset.panel==='categories'&&$('#category-id').value?'keypad':'categories');}
  else if(a==='entry-options'){const expanded=$('#transaction-form').dataset.panel!=='options';transactionPanel(expanded?'options':$('#category-id').value?'keypad':'categories');el.setAttribute('aria-expanded',String(expanded));}
  else if(a==='entry-done'){transactionPanel($('#category-id').value?'keypad':'categories');$('[data-action="entry-options"]').setAttribute('aria-expanded','false');}
  else if(a==='calc-key'){const input=$('#amount');if(id==='C')input.value='';else if(id==='⌫')input.value=input.value.slice(0,-1);else if(id==='='){try{input.value=evaluateExpression(input.value);parseAmount(input.value);$('#form-error').textContent='';}catch(err){error(err.message);}}else if(input.value.length<100){input.value+=id;}input.scrollLeft=input.scrollWidth;}
  else if(a==='delete-transaction'){if(confirm('Delete this transaction? A deleted recurring occurrence will not be added again.')){if(commit(s=>{s.transactions=s.transactions.filter(t=>t.id!==id);})){closeDialog();toast('Transaction deleted.');}}}
  else if(a==='budget-period'){e.preventDefault();budgetSelectedPeriods.set(`${id}:${month}`,el.dataset.start);render();}
  else if(a==='add-budget')budgetDialog();
  else if(a==='edit-budget')budgetDialog(id);
  else if(a==='delete-budget'){if(confirm('Delete this budget? Your transactions will stay.')){if(commit(s=>{s.budgets=s.budgets.filter(b=>b.id!==id);})){closeDialog();toast('Budget deleted.');}}}
  else if(a==='manage-categories')manageCategories();
  else if(a==='new-category')categoryDialog();
  else if(a==='edit-category')categoryDialog(id);
  else if(a==='archive-category'){if(commit(s=>{const c=s.categories.find(c=>c.id===id);c.archived=!c.archived;}))manageCategories();}
  else if(a==='manage-labels')manageLabels();
  else if(a==='new-label')labelDialog();
  else if(a==='edit-label')labelDialog(id);
  else if(a==='delete-label'){if(confirm('Delete this label from all transactions and recurring rules?')){if(commit(s=>{s.labels=s.labels.filter(l=>l.id!==id);for(const t of [...s.transactions,...s.rules.map(r=>r.template)])t.labelIds=t.labelIds.filter(x=>x!==id);})){manageLabels();}}}
  else if(a==='manage-rules')manageRules();
  else if(a==='edit-rule')ruleDialog(id);
  else if(a==='toggle-rule'){if(commit(s=>{const r=s.rules.find(r=>r.id===id);r.active=!r.active;processRules(s);})){manageRules();}}
  else if(a==='remove-rule'){if(confirm('Remove this recurring rule? Existing transactions will stay.')){if(commit(s=>{s.rules=s.rules.filter(r=>r.id!==id);s.transactions.forEach(t=>{if(t.ruleId===id)delete t.ruleId;});})){manageRules();}}}
  else if(a==='scheduled')scheduledDialog();
  else if(a==='export-filtered'){download(transactionsCsv(state,historyRows()),`everyday-transactions-${month}.csv`,'text/csv;charset=utf-8');toast('CSV downloaded.');}
  else if(a==='export-all'){download(transactionsCsv(state),`everyday-all-transactions-${today()}.csv`,'text/csv;charset=utf-8');toast('CSV downloaded.');}
  else if(a==='backup'){backup();toast('Backup downloaded.');}
  else if(a==='restore')$('#restore-file').click();
  else if(a==='reset'){if(confirm('Delete all data in this browser? Download a backup first. This cannot be undone.')){try{const fresh=initialState();saveState(fresh);state=fresh;blocked=false;applyTheme();render();toast('Data reset.');}catch{toast('Browser storage is unavailable.');}}}
});
document.addEventListener('submit',e=>{const form=e.target;if(!form.id.endsWith('-form'))return;e.preventDefault();
  if(form.id==='transaction-form'){dictation.cancel();saveTransaction(form);return;}
  try{
    if(form.id==='budget-form'){const name=$('#budget-name').value.trim(),amount=parseAmount($('#budget-amount').value),startDate=$('#budget-start').value;if(!name)throw Error('Enter a budget name.');if(!validDate(startDate))throw Error('Choose a valid start date.');const b={id:form.dataset.id||uid(),name,amount,startDate,frequency:$('#budget-frequency').value,categoryIds:[...document.querySelectorAll('#budget-categories .selected')].map(x=>x.dataset.id)};if(commit(s=>{const i=s.budgets.findIndex(x=>x.id===b.id);i<0?s.budgets.push(b):s.budgets.splice(i,1,b);})){closeDialog();toast('Budget saved.');}}
    else if(form.id==='category-form'){const name=$('#category-name').value.trim(),icon=$('#category-icon').value.trim();if(!name||!icon)throw Error('Enter a name and icon.');const type=$('#category-type').value;if(state.categories.some(c=>c.id!==form.dataset.id&&c.type===type&&c.name.toLowerCase()===name.toLowerCase()))throw Error('That category name already exists.');const c={id:form.dataset.id||uid(),name,icon,color:$('#category-color').value,type,archived:cat(form.dataset.id)?.archived||false};if(commit(s=>{const i=s.categories.findIndex(x=>x.id===c.id);i<0?s.categories.push(c):s.categories.splice(i,1,c);})){manageCategories();toast('Category saved.');}}
    else if(form.id==='label-form'){const name=$('#label-name').value.trim();if(!name)throw Error('Enter a label name.');if(state.labels.some(l=>l.id!==form.dataset.id&&l.name.toLowerCase()===name.toLowerCase()))throw Error('That label already exists.');const l={id:form.dataset.id||uid(),name};if(commit(s=>{const i=s.labels.findIndex(x=>x.id===l.id);i<0?s.labels.push(l):s.labels.splice(i,1,l);})){manageLabels();toast('Label saved.');}}
    else if(form.id==='rule-form'){const amount=parseAmount($('#rule-amount').value),startDate=$('#rule-date').value,endDate=$('#rule-end').value||null,frequency=$('#rule-frequency').value,description=$('#rule-description').value.trim();if(!validDate(startDate)||endDate&&(!validDate(endDate)||endDate<startDate))throw Error('Choose valid next and end dates.');if(commit(s=>{const r=s.rules.find(r=>r.id===form.dataset.id);Object.assign(r,{startDate,endDate,frequency,nextIndex:0});Object.assign(r.template,{amount,description});processRules(s);})){manageRules();toast('Recurring rule saved.');}}
  }catch(err){error(err.message);}
});
document.addEventListener('input',e=>{if(e.target.closest('#transaction-form'))dictation.cancel();if(e.target.id==='search'){filter.query=e.target.value;$('#history').innerHTML=historyHtml();}});
document.addEventListener('change',e=>{const id=e.target.id,value=e.target.value;if(id==='month'){if(/^\d{4}-\d{2}$/.test(value)&&value>='1900-01'&&value<='2200-12'){month=value;render();}}else if(id.startsWith('filter-')){filter[id.slice(7)]=value;if(filter.from&&filter.to&&filter.from>filter.to){toast('The start date must be before the end date.');}render();}else if(e.target.name==='default-entry-mode'&&['none','manual','dictation'].includes(value)){dictation.cancel();commit(s=>s.settings.defaultEntryMode=value);}else if(id==='theme')commit(s=>s.settings.theme=value);});
$('#restore-file').addEventListener('change',async e=>{const file=e.target.files[0];e.target.value='';if(!file)return;if(file.size>10000000){toast('Backup must be smaller than 10 MB.');return;}try{const candidate=validateState(JSON.parse(await file.text()));if(!confirm(`Replace current data with this backup (${candidate.transactions.length} transactions)? This cannot be undone. Download your current backup first.`))return;processRules(candidate);saveState(candidate);state=candidate;blocked=false;filter={query:'',type:'all',category:'all',label:'all',from:'',to:''};applyTheme();render();toast('Backup restored.');}catch(err){toast('Could not restore: '+err.message);}});
$('#add-transaction').addEventListener('click',()=>transactionDialog());
$('#editor').addEventListener('close',()=>dictation.cancel());
$('#editor').addEventListener('cancel',()=>dictation.cancel());
window.addEventListener('pagehide',()=>dictation.cancel());
$('#editor').addEventListener('click',e=>{if(e.target===$('#editor')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog();}});
window.addEventListener('hashchange',()=>{if(!consumeVoiceEntry())render();window.scrollTo(0,0);});
// Horizontal gestures change the period; vertical gestures continue to scroll.
let overviewGesture=null,ignoreOverviewClickUntil=0,overviewWheel=0,lastOverviewWheel=0;
const overviewGestureAllowed=target=>['home','overview','budgets'].includes(page)&&!$('#editor').open&&!target.closest('input,select,textarea');
function finishOverviewGesture(x,y){if(!overviewGesture)return;const dx=x-overviewGesture.x,dy=y-overviewGesture.y;overviewGesture=null;if(Math.abs(dx)>=60&&Math.abs(dx)>Math.abs(dy)*1.4){ignoreOverviewClickUntil=Date.now()+400;changeOverviewPeriod(dx<0?1:-1);}}
$('#app').addEventListener('touchstart',e=>{overviewGesture=e.touches.length===1&&overviewGestureAllowed(e.target)?{x:e.touches[0].clientX,y:e.touches[0].clientY}:null;},{passive:true});
$('#app').addEventListener('touchmove',e=>{if(!overviewGesture||e.touches.length!==1)return;const dx=e.touches[0].clientX-overviewGesture.x,dy=e.touches[0].clientY-overviewGesture.y;if(Math.abs(dx)>18&&Math.abs(dx)>Math.abs(dy)*1.4)e.preventDefault();},{passive:false});
$('#app').addEventListener('touchend',e=>{if(e.changedTouches.length)finishOverviewGesture(e.changedTouches[0].clientX,e.changedTouches[0].clientY);},{passive:true});
$('#app').addEventListener('touchcancel',()=>{overviewGesture=null;});
$('#app').addEventListener('pointerdown',e=>{if(e.pointerType==='mouse'&&e.button===0&&overviewGestureAllowed(e.target))overviewGesture={x:e.clientX,y:e.clientY};});
$('#app').addEventListener('pointerup',e=>{if(e.pointerType==='mouse')finishOverviewGesture(e.clientX,e.clientY);});
$('#app').addEventListener('click',e=>{if(['home','overview','budgets'].includes(page)&&Date.now()<ignoreOverviewClickUntil){e.preventDefault();e.stopImmediatePropagation();}},{capture:true});
$('#app').addEventListener('wheel',e=>{if(!overviewGestureAllowed(e.target)||e.ctrlKey||Math.abs(e.deltaX)<=Math.abs(e.deltaY)||Math.abs(e.deltaX)<2)return;e.preventDefault();const now=Date.now();if(now-lastOverviewWheel>250)overviewWheel=0;lastOverviewWheel=now;overviewWheel+=e.deltaX;if(Math.abs(overviewWheel)>65){changeOverviewPeriod(overviewWheel>0?1:-1);overviewWheel=0;}},{passive:false});
document.addEventListener('keydown',e=>{if(['home','overview','budgets'].includes(page)&&!$('#editor').open&&!e.target.closest('input,select,textarea')&&['ArrowLeft','ArrowRight'].includes(e.key)){e.preventDefault();changeOverviewPeriod(e.key==='ArrowRight'?1:-1);}});
window.addEventListener('storage',e=>{if(e.key===STORAGE_KEY){try{state=loadState();blocked=false;applyTheme();render();if($('#editor').open)closeDialog();toast('Updated from another tab.');}catch{blocked=true;render();}}});
document.addEventListener('visibilitychange',()=>{if(document.hidden)dictation.cancel();if(!document.hidden){catchUp();render();openDefaultTransaction();}});
matchMedia('(prefers-color-scheme: dark)').addEventListener('change',()=>{if(state.settings.theme==='system')applyTheme();});
if(!isNativeApp()&&'serviceWorker' in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});
setupAndroidBack(closeDialog);
render();
if(!consumeVoiceEntry())openDefaultTransaction();
window.addEventListener('pageshow',e=>{if(e.persisted)openDefaultTransaction();});
